// true of the old ones only: the "enter the key again" flag, and the tool
// list the old address answered with.
func (q *Queries) UpdateServer(ctx context.Context, arg UpdateServerParams) (UpdateServerRow, error) {
	row := q.db.QueryRow(ctx, updateServer,
		arg.Name,
		arg.ServerConfig,
		arg.ID,
		arg.UserID,
	)
	var i UpdateServerRow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.ConnectorType,
		&i.Enabled,
		&i.IsIndexable,
		&i.LastIndexedAt,
		&i.Config,
		&i.EnableVisionLlm,
		&i.PeriodicIndexingEnabled,
		&i.IndexingFrequencyMinutes,
		&i.NextScheduledAt,
		&i.UserID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
